BUG DESCRIPTION: A component calls `setData` inside an effect whose dependency list includes `data`, so every update retriggers the effect and causes an infinite rerender loop.

CODE:
import React, { useEffect, useState } from 'react';

export default function DataLoader({ fetchData }) {
  const [data, setData] = useState('');

  useEffect(() => {
    setData(fetchData());
  }, [data, fetchData]);

  return <div>{data}</div>;
}

